"use client";

import React, { useEffect, useState, useCallback, useRef } from "react";
// ★ 修正: usePathname を追加し、next/navigation からインポート
import { useRouter, usePathname } from "next/navigation";
import { sendEmailVerification } from "firebase/auth";
// useAuth から reloadAuthToken を取得します
import { useAuth } from "@/hooks/useSanctumAuth";

// 定数: 認証状態をチェックする間隔（ミリ秒）
const CHECK_INTERVAL_MS = 3000; // 3秒ごとにチェック
// 認証完了後のリダイレクト先
const POST_VERIFY_REDIRECT_ROUTE = "/mypage/profile?verified=true";

export default function VerifyEmailPage() {
  const router = useRouter();
  // ★ 修正: usePathname で現在のパスを取得
  const pathname = usePathname();

  const { user, auth, isLoading, reloadAuthToken } = useAuth();

  const [statusMessage, setStatusMessage] = useState<string | null>(null);
  const [isSending, setIsSending] = useState(false);
  const [isReloading, setIsReloading] = useState(false); // トークン再取得中
  const intervalRef = useRef<number | null>(null);

  // ---------------------------------------------
  // 副作用: 認証状態の監視とリダイレクト
  // ---------------------------------------------

  // インターバルを開始/クリアする関数を定義
  const checkVerificationStatus = useCallback(() => {
    if (intervalRef.current !== null) return;

    console.log("未認証状態: 3秒ごとにFirebaseユーザーをリロードします。");

    const id = window.setInterval(async () => {
      if (auth?.currentUser) {
        try {
          // Firebase側のユーザー情報をリロードして最新の認証状態を取得
          await auth.currentUser.reload();
          console.log(
            "Firebase user reloaded. Checking verification status...",
          );
        } catch (error) {
          console.warn("Firebase user reload failed:", error);
        }
      }
    }, CHECK_INTERVAL_MS);

    intervalRef.current = id;
    return id as unknown as number;
  }, [auth]);

  // クリーンアップ処理を共通化
  const clearCheckInterval = useCallback(() => {
    if (intervalRef.current !== null) {
      window.clearInterval(intervalRef.current);
      intervalRef.current = null;
      console.log("✅ 認証チェックインターバルを停止しました。");
    }
  }, []);

  useEffect(() => {
    // 1. 認証状態が解決するまで待つ or トークン再取得中は待つ
    if (isLoading || isReloading) return;

    // ★★★ 修正ポイント 1: URLパラメータからのトークン取得と処理（リダイレクト安定化） ★★★
    const params = new URLSearchParams(window.location.search);
    const isVerifiedFromRedirect = params.get("verified") === "true";

    // Laravelからの認証成功リダイレクトを検知した場合
    if (isVerifiedFromRedirect) {
      clearCheckInterval();

      // URLパラメータ（token, verified=trueなど）をクリアし、現在のパス名に置き換える
      // ★ router.replace(router.pathname, undefined, { shallow: true }); の App Router 対応版
      router.replace(pathname);

      if (!isReloading) {
        setIsReloading(true);
        console.log(
          "Laravel認証リダイレクトを検知。Sanctumセッション確立のため reloadAuthToken を実行します。",
        );

        reloadAuthToken()
          .then(() => {
            console.log("✅ トークンとプロフィール情報のリフレッシュに成功。");
            router.replace(POST_VERIFY_REDIRECT_ROUTE);
          })
          .catch((error) => {
            console.error(
              "リダイレクト後のSanctumセッション確立に失敗:",
              error,
            );
            setStatusMessage(
              "認証情報の更新に失敗しました。再度ログインしてください。",
            );
          })
          .finally(() => {
            setIsReloading(false);
          });
      }
      return;
    }
    // ★★★ 修正終わり ★★★

    // 2. 未ログイン（Firebaseのuserオブジェクトがない状態） → login へ
    if (!user) {
      clearCheckInterval();
      console.log("未ログイン状態を検知。/loginへリダイレクト。");
      router.replace("/login");
      return;
    }

    // 3. すでにメール認証済み（userが存在し、emailVerifiedがtrue）
    if (user.emailVerified) {
      clearCheckInterval();

      // Firebase認証完了後、SanctumセッションとBackendUserの状態を強制的に最新化
      if (!isReloading) {
        setIsReloading(true);
        console.log(
          "Firebaseメール認証完了。Sanctumセッション確立のため reloadAuthToken を実行します。",
        );

        reloadAuthToken()
          .then(() => {
            console.log("✅ トークンとプロフィール情報のリフレッシュに成功。");
            // 状態が完全に更新された後、安全なルートへリダイレクト
            router.replace(POST_VERIFY_REDIRECT_ROUTE);
          })
          .catch((error) => {
            // リロード失敗時はエラーメッセージを表示するか、ログアウト
            console.error(
              "Sanctumセッション確立/トークンリフレッシュに失敗:",
              error,
            );
            setStatusMessage(
              "認証情報の更新に失敗しました。再度ログインしてください。",
            );
          })
          .finally(() => {
            setIsReloading(false);
          });
      }
      return;
    }

    // 4. 未認証でこのページに留まる場合: 認証状態を定期的にチェックするインターバルを開始
    if (!user.emailVerified && intervalRef.current === null) {
      checkVerificationStatus();
    }

    return () => {
      clearCheckInterval();
    };
  }, [
    isLoading,
    user,
    router,
    checkVerificationStatus,
    clearCheckInterval,
    reloadAuthToken,
    isReloading,
    pathname, // ★ 依存配列に pathname を追加
  ]);

  // Still loading
  if (isLoading || isReloading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-100">
        <div className="animate-spin rounded-full h-10 w-10 border-t-2 border-b-2 border-blue-500 mx-auto"></div>
        <p className="ml-3 text-gray-700">
          {isReloading ? "認証情報を確定中..." : "認証状態を確認中..."}
        </p>
      </div>
    );
  }

  // 認証済みだと useEffect で移動するので return null
  if (!user || user.emailVerified) return null;

  // ---------------------------------------------
  // 認証メール再送 (ロジック修正)
  // ---------------------------------------------
  const handleResend = async () => {
    if (!auth?.currentUser) {
      setStatusMessage(
        "エラー: ログイン状態が確認できません。再度ログインしてください。",
      );
      return;
    }

    setIsSending(true);
    setStatusMessage(null);

    try {
      // ★★★ 最終修正ポイント 1: 強制リロード/リフレッシュ (念のため両方実行) ★★★
      await auth.currentUser.reload();
      await auth.currentUser.getIdToken(true);

      // ★★★ 最終修正ポイント 2: ActionCodeSettings を定義 ★★★
      const actionCodeSettings = {
        // メール認証後のリダイレクト先を指定（通常はフロントエンドのトップページなど）
        // この URL は Firebase Console の「Authentication -> テンプレート -> メールアドレスの確認」で許可されている必要があります。
        // ここでは、現在のページ (VerifyEmailPage) に戻るか、安全なルートを指定
        url: window.location.href, // 現在の URL を使用
        handleCodeInApp: false, // In-App 認証ではないことを明示
        // android: { packageName: '...', installApp: true, minimumVersion: '12' }, // 省略
        // iOS: { bundleId: '...' } // 省略
      };

      console.log(
        "最新のトークンを取得後、ActionCodeSettings を使用して再送を開始します。",
      );

      // ActionCodeSettings を第2引数として渡す
      await sendEmailVerification(auth.currentUser, actionCodeSettings);

      setStatusMessage(
        "新しい認証メールを送信しました。メールボックスを確認してください。",
      );
    } catch (error) {
      console.error("Failed to resend email verification:", error);

      const errorMessage = (error as any).message || "不明なエラーです。";

      setStatusMessage(
        `認証メールの再送に失敗しました。時間をおいてお試しください。 (${errorMessage})`,
      );
    } finally {
      setIsSending(false);
    }
  };

  // ---------------------------------------------
  // レンダリング (変更なし)
  // ---------------------------------------------

  return (
    <div className="min-h-screen flex justify-center items-start pt-20 bg-gray-50">
      <div className="w-full max-w-xl p-8 bg-white rounded-lg shadow-xl">
        <h2 className="text-3xl font-extrabold text-indigo-600 mb-6 border-b-2 pb-3 text-center">
          💌 メール認証のお願い
        </h2>

        <div className="space-y-4 text-gray-700 text-center">
          <p className="text-xl font-medium">ご登録ありがとうございます！</p>
          <p className="text-base">
            以下のメールアドレス宛に**認証メール**を送付しました。
            <br />
            <span className="font-bold text-lg text-blue-700">
              {user.email ?? "メールアドレス不明"}
            </span>
          </p>
          <div className="p-4 bg-yellow-50 border border-yellow-300 rounded-md shadow-sm">
            <p className="text-base font-semibold text-red-600">
              メール内のリンクをクリックして認証を完了してください。
            </p>
            <p className="text-sm mt-1 text-gray-600">
              認証が完了すると、このページは自動的に移動します。
            </p>
          </div>
        </div>

        {statusMessage && (
          <div className="mt-6 p-3 bg-green-100 text-green-700 rounded text-sm font-medium text-center border border-green-300">
            {statusMessage}
          </div>
        )}

        {/* 開発用メール確認 */}
        <div className="mt-8 text-center">
          <a
            href="http://localhost:8025"
            target="_blank"
            rel="noopener noreferrer"
            className="inline-block px-6 py-2 bg-gray-700 text-white rounded-md font-semibold hover:bg-gray-800 transition duration-150 shadow-md text-sm"
          >
            👨‍💻 開発用: メールボックスを確認 (MailHog)
          </a>
        </div>

        {/* 認証メール再送 */}
        <form
          onSubmit={(e) => {
            e.preventDefault();
            handleResend();
          }}
          className="mt-6"
        >
          <button
            type="submit"
            disabled={isSending || isReloading}
            className="w-full bg-indigo-600 text-white py-3 rounded-md font-bold text-lg hover:bg-indigo-700 transition duration-150 shadow-lg disabled:bg-gray-400 disabled:cursor-not-allowed"
          >
            {isSending
              ? "送信中..."
              : isReloading
                ? "認証情報の確定中..."
                : "認証メールを再送する"}
          </button>
        </form>
      </div>
    </div>
  );
}
